125: /** Iterative Tarjan over unit-level obligatory edges — detects quotient cycles. */
126: function unitQuotientHasCycle(unitIds: string[], edges: Array<[string, string]>): boolean {
127:   const adjacency = new Map<string, string[]>();
128:   for (const unitId of unitIds) adjacency.set(unitId, []);
129:   for (const [from, to] of edges) adjacency.get(from)?.push(to);
130:   const index = new Map<string, number>();
131:   const low = new Map<string, number>();
132:   const onStack = new Set<string>();
133:   const stack: string[] = [];
134:   let counter = 0;
135:   let cyclic = false;
136:   for (const root of unitIds) {
137:     if (index.has(root)) continue;
138:     const frames: Array<{ node: string; cursor: number }> = [{ node: root, cursor: 0 }];
139:     index.set(root, counter); low.set(root, counter); counter += 1;
140:     stack.push(root); onStack.add(root);
141:     while (frames.length > 0) {
142:       const frame = frames[frames.length - 1];
143:       const successors = adjacency.get(frame.node) ?? [];
144:       if (frame.cursor < successors.length) {
145:         const next = successors[frame.cursor]!;
146:         frame.cursor += 1;
147:         if (!index.has(next)) {
148:           index.set(next, counter); low.set(next, counter); counter += 1;
149:           stack.push(next); onStack.add(next);
150:           frames.push({ node: next, cursor: 0 });
151:         } else if (onStack.has(next)) {
152:           low.set(frame.node, Math.min(low.get(frame.node)!, index.get(next)!));
153:         }
154:       } else {
155:         frames.pop();
156:         if (frames.length > 0) {
157:           const parent = frames[frames.length - 1]!.node;
158:           low.set(parent, Math.min(low.get(parent)!, low.get(frame.node)!));
159:         }
160:         if (low.get(frame.node) === index.get(frame.node)) {
161:           let popped = 0;
162:           for (;;) {
163:             const member = stack.pop()!;
164:             onStack.delete(member);
165:             popped += 1;
166:             if (member === frame.node) break;
167:           }
168:           if (popped > 1) cyclic = true;
169:         }
170:       }
171:     }
172:   }
173:   return cyclic;
174: }
