194:       if (context.has(fn)) diagnostics.push({ code: "owned_context_overlap", unitId: unit.unitId, detail: `fn ${fn} both owned and context` });
195:     }
196:   }
197:   const unitIds = new Set(plan.units.map(u => u.unitId));
198:   const obligatoryEdges: Array<[string, string]> = [];
