-/**
- * L7 — Deterministic scheduler simulator and independent oracle.
- *
- * Contract source: docs/missions/re-graph-scheduler/contract/CONTRAT.md (v1, frozen)
- * Mission source: docs/missions/re-graph-scheduler/ORDRE_MISSION.md §11, §12, §15, §17.2, §17.3
- *
- * NON-GOALS (do not promote this module beyond its level):
- * - No LLM call, no IDA access, no native bridge. Workers are simulated records;
- *   the input types below carry no provider/model/session field at all.
- * - No native storage proof. Every commit is written to an in-memory
- *   `SimStore` labelled "sim-fixture-store". Outbox/lease/CAS semantics are
- *   re-implementations for testing; the real SQLite store (L6) must be tested
- *   by L6 integration tests, not by this simulator. See SIM_INTEGRATION_LIMITS.
- * - The engine does NOT compute SCCs, clustering or priorities from the graph.
- *   It consumes an immutable plan-shaped export. SCC figures used to BUILD test
- *   scenarios live in the benchmark generator (test data, clearly labelled).
- *
- * Determinism: integer ticks, total event order (time, seq), canonical
- * iteration order, no Date.now(), no Math.random(). The same scenario input
- * always produces the same trace hash.
- */
-
-import { canonical, hash } from "./validation";
-
-// ---------------------------------------------------------------------------
-// 1. Errors
-// ---------------------------------------------------------------------------
-
-export type SimErrorCode =
-  | "plan_non_conformant"
-  | "unknown_unit"
-  | "already_reserved"
-  | "duplicate_commit"
-  | "fenced_late_commit"
-  | "unit_not_active"
-  | "max_attempts_exceeded"
-  | "horizon_exceeded"
-  | "envelope_line_limit"
-  | "envelope_over_budget"
-  | "unsafe_manifest_path";
-
-export class SimError extends Error {
-  constructor(readonly code: SimErrorCode, message: string, readonly detail?: unknown) {
-    super(`simulator[${code}]: ${message}`);
-  }
-}
-
-// ---------------------------------------------------------------------------
-// 2. Plan input (immutable export consumed by the engine)
-// ---------------------------------------------------------------------------
-
-export type SimPublicationLevel = 1 | 2;
-
-export type SimUnitState =
-  | "PENDING" | "BLOCKED" | "READY" | "RESERVED" | "RUNNING"
-  | "VALIDATING" | "COMMITTED" | "RETRYABLE" | "FAILED"
-  | "STALE" | "CANCELLED" | "STOP_PENDING" | "QUARANTINED";
-
-export interface SimPrerequisite {
-  producerUnitId: string | null;
-  kind: "obligatory" | "optional" | "external_satisfied" | "unknown_unresolved" | "non_blocking";
-  requiredPublicationLevel: SimPublicationLevel;
-  dispensed: boolean;
-  dispensationReason?: string | null;
-}
-
-export interface SimUnitInput {
-  unitId: string;
-  ownedFunctionIds: string[];
-  contextFunctionIds: string[];
-  investigationKind: "structural" | "decompilation" | "semantification";
-  /** Simulator extension: workers whose profile differs are ineligible. Absent = any profile. */
-  requiredProfile?: string;
-  requiredPublicationLevel: SimPublicationLevel;
-  prerequisites: SimPrerequisite[];
-  /** Direct exclusive conflicts, canonical resource keys. Never transitively closed. */
-  conflicts: Array<{ resourceKey: string }>;
-  /** True when the unit covers an SCC (exclusive dependency unit, CONTRAT §3.12). */
-  sccExclusive?: boolean;
-  knowledgeRevision: number;
-  /** Optional context manifest content used by the UTF-8 envelope oracle. */
-  contextManifestLines?: string[];
-}
-
-export interface SimG1EdgeInput {
-  fromUnitId: string; // work of the callee (producer)
-  toUnitId: string;   // work of the caller (consumer)
-  kind: "obligatory" | "optional" | "non_blocking";
-  callSourceFunctionId: string;
-  callDestinationFunctionId: string;
-}
-
-export interface SimPlanInput {
-  planId: string;
-  missionId: string;
-  knowledgeRevision: number;
-  units: SimUnitInput[];
-  g1Edges: SimG1EdgeInput[];
-  g2Conflicts: Array<{ id: string; resourceKey: string }>;
-  budgets: { contextEnvelopeMaxUtf8Bytes: number; nativeLineCharLimit: number };
-  /** Include-closure candidates. Absent = every unit is a candidate. */
-  selectedUnitIds?: string[];
-  decisions?: Array<{ id: string; unitId: string; action: "include" | "defer" | "dispense" | "exclude_budget"; reason: string }>;
-}
-
-// ---------------------------------------------------------------------------
-// 3. Conformance oracle (consumer-side checks, CONTRAT §2/§5/§9)
-// ---------------------------------------------------------------------------
-
-export interface SimDiagnostic {
-  code:
-    | "duplicate_unit"
-    | "duplicate_possession"
-    | "owned_context_overlap"
-    | "unknown_g1_unit"
-    | "g1_prerequisite_mismatch"
-    | "unknown_prerequisite_producer"
-    | "closure_omits_producer"
-    | "quotient_cycle"
-    | "empty_unit";
-  unitId?: string;
-  detail: string;
-}
-
-/** Iterative Tarjan over unit-level obligatory edges — detects quotient cycles. */
-function unitQuotientHasCycle(unitIds: string[], edges: Array<[string, string]>): boolean {
-  const adjacency = new Map<string, string[]>();
-  for (const unitId of unitIds) adjacency.set(unitId, []);
-  for (const [from, to] of edges) adjacency.get(from)?.push(to);
-  const index = new Map<string, number>();
-  const low = new Map<string, number>();
-  const onStack = new Set<string>();
-  const stack: string[] = [];
-  let counter = 0;
-  let cyclic = false;
-  for (const root of unitIds) {
-    if (index.has(root)) continue;
-    const frames: Array<{ node: string; cursor: number }> = [{ node: root, cursor: 0 }];
-    index.set(root, counter); low.set(root, counter); counter += 1;
-    stack.push(root); onStack.add(root);
-    while (frames.length > 0) {
-      const frame = frames[frames.length - 1];
-      const successors = adjacency.get(frame.node) ?? [];
-      if (frame.cursor < successors.length) {
-        const next = successors[frame.cursor]!;
-        frame.cursor += 1;
-        if (!index.has(next)) {
-          index.set(next, counter); low.set(next, counter); counter += 1;
-          stack.push(next); onStack.add(next);
-          frames.push({ node: next, cursor: 0 });
-        } else if (onStack.has(next)) {
-          low.set(frame.node, Math.min(low.get(frame.node)!, index.get(next)!));
-        }
-      } else {
-        frames.pop();
-        if (frames.length > 0) {
-          const parent = frames[frames.length - 1]!.node;
-          low.set(parent, Math.min(low.get(parent)!, low.get(frame.node)!));
-        }
-        if (low.get(frame.node) === index.get(frame.node)) {
-          let popped = 0;
-          for (;;) {
-            const member = stack.pop()!;
-            onStack.delete(member);
-            popped += 1;
-            if (member === frame.node) break;
-          }
-          if (popped > 1) cyclic = true;
-        }
-      }
-    }
-  }
-  return cyclic;
-}
-
-export function validateSimPlan(plan: SimPlanInput): SimDiagnostic[] {
-  const diagnostics: SimDiagnostic[] = [];
-  const seen = new Set<string>();
-  const possession = new Map<string, string>();
-  for (const unit of plan.units) {
-    if (seen.has(unit.unitId)) diagnostics.push({ code: "duplicate_unit", unitId: unit.unitId, detail: "unitId declared twice" });
-    seen.add(unit.unitId);
-    if (unit.ownedFunctionIds.length === 0) diagnostics.push({ code: "empty_unit", unitId: unit.unitId, detail: "unit owns no function" });
-    for (const fn of unit.ownedFunctionIds) {
-      const owner = possession.get(fn);
-      if (owner !== undefined && owner !== unit.unitId) {
-        diagnostics.push({ code: "duplicate_possession", unitId: unit.unitId, detail: `fn ${fn} already owned by ${owner}` });
-      } else {
-        possession.set(fn, unit.unitId);
-      }
-    }
-    const context = new Set(unit.contextFunctionIds);
-    for (const fn of unit.ownedFunctionIds) {
-      if (context.has(fn)) diagnostics.push({ code: "owned_context_overlap", unitId: unit.unitId, detail: `fn ${fn} both owned and context` });
-    }
-  }
-  const unitIds = new Set(plan.units.map(u => u.unitId));
-  const obligatoryEdges: Array<[string, string]> = [];
-  for (const edge of plan.g1Edges) {
-    if (!unitIds.has(edge.fromUnitId) || !unitIds.has(edge.toUnitId)) {
-      diagnostics.push({ code: "unknown_g1_unit", detail: `g1 edge ${edge.fromUnitId} -> ${edge.toUnitId} references an unknown unit` });
-      continue;
-    }
-    if (edge.kind === "obligatory") {
-      obligatoryEdges.push([edge.fromUnitId, edge.toUnitId]);
-      const matching = plan.units
-        .filter(u => u.unitId === edge.toUnitId)
-        .flatMap(u => u.prerequisites)
-        .some(p => p.kind === "obligatory" && !p.dispensed && p.producerUnitId === edge.fromUnitId);
-      if (!matching) {
-        diagnostics.push({ code: "g1_prerequisite_mismatch", unitId: edge.toUnitId, detail: `obligatory g1 edge from ${edge.fromUnitId} has no matching obligatory prerequisite` });
-      }
-    }
-  }
-  for (const unit of plan.units) {
-    for (const prerequisite of unit.prerequisites) {
-      if (prerequisite.kind === "obligatory" && !prerequisite.dispensed && prerequisite.producerUnitId !== null && !unitIds.has(prerequisite.producerUnitId)) {
-        diagnostics.push({ code: "unknown_prerequisite_producer", unitId: unit.unitId, detail: `prerequisite references unknown producer ${prerequisite.producerUnitId}` });
-      }
-    }
-  }
-  // Include-closure: a selected consumer requires every obligatory non-dispensed producer (CONTRAT §3.12).
-  const selected = plan.selectedUnitIds === undefined ? null : new Set(plan.selectedUnitIds);
-  if (selected !== null) {
-    for (const unit of plan.units) {
-      if (!selected.has(unit.unitId)) continue;
-      for (const prerequisite of unit.prerequisites) {
-        if (prerequisite.kind !== "obligatory" || prerequisite.dispensed || prerequisite.producerUnitId === null) continue;
-        if (!selected.has(prerequisite.producerUnitId)) {
-          diagnostics.push({ code: "closure_omits_producer", unitId: unit.unitId, detail: `selected consumer omits obligatory producer ${prerequisite.producerUnitId}` });
-        }
-      }
-    }
-  }
-  // Quotient of obligatory dependencies must be a DAG (CONTRAT §3.12: fusion must not create a cycle).
-  if (unitQuotientHasCycle([...unitIds].sort(compareText), obligatoryEdges)) {
-    diagnostics.push({ code: "quotient_cycle", detail: "obligatory prerequisite quotient contains a cycle (bad fusion?)" });
-  }
-  return diagnostics;
-}
-
-// ---------------------------------------------------------------------------
-// 4. Scenario specification
-// ---------------------------------------------------------------------------
-
-export type SimRole = "A" | "B" | "R";
-export type SimPolicyKind =
-  | "sequential" | "fixed_groups" | "levels" | "fifo"
-  | "event_driven" | "critical_path" | "heterogeneous";
-
-export interface SimWorkerSpec { profile: string; accountId: string }
-
-export interface SimDurations { A: number; B: number; R: number }
-
-export type SimDurationsSpec =
-  | SimDurations
-  | Map<string, SimDurations>
-  | ((unitId: string) => SimDurations);
-
-export type SimIncident =
-  | { kind: "crash_before_admit"; atTick: number; unitId: string }
-  | { kind: "crash_after_admit"; atTick: number; unitId: string }
-  | { kind: "response_lost"; unitId: string; reconcileAfter?: number }
-  | { kind: "heartbeat_lost"; atTick: number; unitId: string }
-  | { kind: "lease_expired_worker_active"; atTick: number; unitId: string }
-  | { kind: "ambiguous_stop"; atTick: number; unitId: string; confirmWindow: number }
-  | { kind: "late_result"; unitId: string; delayTicks: number }
-  | { kind: "double_commit_attempt"; atTick: number; unitId: string }
-  | { kind: "pause"; fromTick: number; toTick: number }
-  | { kind: "new_conflict"; atTick: number; resourceKey: string; unitIdA: string; unitIdB: string }
-  | { kind: "new_dependency"; atTick: number; consumerUnitId: string; producerUnitId: string }
-  | { kind: "bulletin"; atTick: number; unitId: string; authorRole: "A" | "B" | "R" | "unauthorized"; canonical: boolean };
-
-export interface SimConfig {
