-  workers: SimWorkerSpec[];
-  /** Max concurrent running jobs per account. Absent account = unlimited. */
-  accountQuotas?: Record<string, number>;
-  leaseTicks: number;
-  heartbeatEvery: number;
-  validationTicks: number;
-  maxAttempts: number;
-  maxTicks: number;
-  policy: SimPolicyKind;
