-  /** fixed_groups only. */
-  groupSize?: number;
-  recordTrace?: boolean;
-}
-
-export interface SimScenario {
-  plan: SimPlanInput;
-  config: SimConfig;
-  durations: SimDurationsSpec;
-  incidents?: SimIncident[];
-  /** Documentary only: the engine never draws from it (no RNG in decisions). */
-  seed?: string;
-}
-
-// ---------------------------------------------------------------------------
-// 5. Trace, store, metrics, results
-// ---------------------------------------------------------------------------
-
-export interface SimTraceEntry { t: number; seq: number; ev: string; [key: string]: unknown }
-
-export interface SimCommitRecord {
-  commitId: string;
-  inputRevision: number;
-  outputRevision: number;
-  unitId: string;
-  resultIds: string[];
-  validatedFactIds: string[];
-  publicationLevel: SimPublicationLevel;
-  publicationTargetId: "sim-fixture-store";
-  readbackStatus: "verified" | "mismatch";
-  readbackHash: string;
-  futurePrerequisiteEffect: "satisfies" | "does_not_satisfy";
-  isGitCommit: false;
-  simulated: true;
-}
-
-export interface SimDeltaRecord {
-  deltaId: string;
-  fromRevision: number;
-  toRevision: number;
-  affectedFunctionIds: string[];
-  origin: string;
-  validation: "fixture-only";
-  potentialImpact: "local" | "structural" | "none";
-  simulated: true;
-}
-
-export interface SimBulletinRecord {
-  atTick: number;
-  unitId: string;
-  authorRole: "A" | "B" | "R" | "unauthorized";
-  canonical: boolean;
-  accepted: boolean;
-  rejectionReason: string | null;
-}
-
-/** Fixture-level store. NOT the L6 SQLite store. */
-export class SimStore {
-  readonly publicationTargetId = "sim-fixture-store" as const;
-  private commits = new Map<string, SimCommitRecord>();
-  private revisionCounter: number;
-  readonly deltas: SimDeltaRecord[] = [];
-  readonly bulletins: SimBulletinRecord[] = [];
-  readonly rejectedCommits: Array<{ unitId: string; code: SimErrorCode; atTick: number }> = [];
-
-  constructor(initialRevision: number) { this.revisionCounter = initialRevision; }
-  get revision(): number { return this.revisionCounter; }
-  getCommit(unitId: string): SimCommitRecord | undefined { return this.commits.get(unitId); }
-  get committedCount(): number { return this.commits.size; }
-
-  /** Idempotent single write per unit; a second write is a contract violation. */
-  write(commit: Omit<SimCommitRecord, "commitId" | "isGitCommit" | "simulated">, atTick: number): SimCommitRecord {
-    if (this.commits.has(commit.unitId)) {
-      this.rejectedCommits.push({ unitId: commit.unitId, code: "duplicate_commit", atTick });
-      throw new SimError("duplicate_commit", `unit ${commit.unitId} already committed at revision ${this.commits.get(commit.unitId)!.outputRevision}`);
-    }
-    const full: SimCommitRecord = { ...commit, commitId: hash(canonical(commit)), isGitCommit: false, simulated: true };
-    this.commits.set(commit.unitId, full);
-    this.revisionCounter = Math.max(this.revisionCounter, full.outputRevision);
-    return full;
-  }
-
-  addDelta(delta: Omit<SimDeltaRecord, "deltaId" | "simulated">): SimDeltaRecord {
-    const full: SimDeltaRecord = { ...delta, deltaId: hash(canonical(delta)), simulated: true };
-    this.deltas.push(full);
-    return full;
-  }
-}
-
-export interface SimUnitFinalState {
-  unitId: string;
-  state: SimUnitState;
