-/** Builds the context manifest envelope; budgets count UTF-8 bytes, never UTF-16 code units. */
-export function buildContextEnvelope(
-  unit: Pick<SimUnitInput, "unitId" | "ownedFunctionIds" | "contextFunctionIds" | "contextManifestLines" | "knowledgeRevision">,
-  budgets: { contextEnvelopeMaxUtf8Bytes: number; nativeLineCharLimit: number },
-): SimEnvelope {
-  const lines = unit.contextManifestLines ?? [
-    `unit: ${unit.unitId}`,
-    `revision: ${unit.knowledgeRevision}`,
-    ...unit.ownedFunctionIds.map(fn => `owned: ${fn}`),
-    ...unit.contextFunctionIds.map(fn => `context: ${fn}`),
-  ];
-  const envelope = { envelopeVersion: 1, lines, unitId: unit.unitId };
-  const serialized = canonical(envelope);
-  const utf8Bytes = utf8ByteLength(serialized);
-  const withinLineLimit = lines.every(line => line.length <= budgets.nativeLineCharLimit);
-  const withinBudget = utf8Bytes <= budgets.contextEnvelopeMaxUtf8Bytes;
-  return { lines, utf8Bytes, charLength: serialized.length, withinLineLimit, withinBudget };
-}
