-/** Pure path oracle for context manifests. Native junction/symlink behaviour is an integration obligation. */
-export function assertSafeManifestPath(root: string, relative: string): string {
-  if (relative.length === 0) throw new SimError("unsafe_manifest_path", "empty relative path");
-  if (/^[a-zA-Z]:/.test(relative) || relative.startsWith("\\\\") || relative.startsWith("//")) {
-    throw new SimError("unsafe_manifest_path", `absolute or UNC path: ${relative}`);
-  }
-  const segments = relative.split(/[\\/]/);
-  if (segments.some(segment => segment === "..")) {
-    throw new SimError("unsafe_manifest_path", `traversal segment in: ${relative}`);
-  }
-  const normalized = segments.filter(segment => segment.length > 0 && segment !== ".").join("/");
-  return `${root.replace(/[\\/]+$/, "")}/${normalized}`;
-}
