-
-export function planShape(plan: SimPlanInput, durations: SimDurationsSpec, validationTicks: number): PlanShapeInfo {
-  const dur = resolveDurations(durations);
-  const span = new Map<string, number>();
-  let totalWork = 0;
-  for (const unit of plan.units) {
-    const d = dur(unit.unitId);
-    span.set(unit.unitId, Math.max(d.A, d.B) + d.R + validationTicks);
-    totalWork += d.A + d.B + d.R + validationTicks;
-  }
-  const consumers = new Map<string, string[]>();
-  for (const unit of plan.units) consumers.set(unit.unitId, []);
-  for (const unit of plan.units) {
-    for (const prerequisite of unit.prerequisites) {
-      if (prerequisite.kind !== "obligatory" || prerequisite.dispensed || prerequisite.producerUnitId === null) continue;
-      const list = consumers.get(prerequisite.producerUnitId);
-      if (list !== undefined && !list.includes(unit.unitId)) list.push(unit.unitId);
-    }
-  }
-  // Longest path by memoized DFS; the plan is validated acyclic beforehand.
-  const memo = new Map<string, number>();
-  const tail = (unitId: string): number => {
-    const cached = memo.get(unitId);
-    if (cached !== undefined) return cached;
-    memo.set(unitId, 0); // cycle guard; validated plans never hit it
-    let best = 0;
-    for (const consumer of consumers.get(unitId) ?? []) {
-      best = Math.max(best, (span.get(consumer) ?? 0) + tail(consumer));
-    }
-    memo.set(unitId, best);
-    return best;
-  };
-  let criticalPath = 0;
-  for (const unit of plan.units) {
-    criticalPath = Math.max(criticalPath, (span.get(unit.unitId) ?? 0) + tail(unit.unitId));
-  }
-  return {
-    unitSpan: unitId => span.get(unitId) ?? 0,
-    criticalPathTicks: criticalPath,
-    totalWorkTicks: totalWork,
-  };
-}
