-function resolveDurations(spec: SimDurationsSpec): (unitId: string) => SimDurations {
-  if (typeof spec === "function") return spec;
-  if (spec instanceof Map) return unitId => spec.get(unitId) ?? { A: 1, B: 1, R: 1 };
-  return () => spec;
-}
