-/** Lazy-deletion binary heap: stale tickets are dropped on pop. */
-class ReadyHeap {
-  private a: HeapEntry[] = [];
-  constructor(private readonly less: (x: UnitRuntime, y: UnitRuntime) => number) {}
-  get size(): number { return this.a.length; }
-  push(unit: UnitRuntime): void {
-    unit.heapTicket += 1;
-    const entry: HeapEntry = { unit, ticket: unit.heapTicket };
-    const a = this.a;
-    a.push(entry);
-    let i = a.length - 1;
-    while (i > 0) {
-      const p = (i - 1) >> 1;
-      if (this.less(a[i]!.unit, a[p]!.unit) < 0) { const tmp = a[i]!; a[i] = a[p]!; a[p] = tmp; i = p; } else break;
-    }
-  }
-  pop(): UnitRuntime | undefined {
-    const a = this.a;
-    while (a.length > 0) {
-      const top = a[0]!;
-      const last = a.pop()!;
-      if (a.length > 0) {
-        a[0] = last;
-        let i = 0;
-        for (;;) {
-          const l = 2 * i + 1;
-          const r = l + 1;
-          let m = i;
-          if (l < a.length && this.less(a[l]!.unit, a[m]!.unit) < 0) m = l;
-          if (r < a.length && this.less(a[r]!.unit, a[m]!.unit) < 0) m = r;
-          if (m === i) break;
-          const tmp = a[i]!; a[i] = a[m]!; a[m] = tmp;
-          i = m;
-        }
